import math
def priority(task, state, k=0.5, m=2.0, b=0.5, q=4.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    slack = task.due - est - state.now
    mean_est = max(state.mean_est, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    # Pure ATC when congested, otherwise WSPT+aging to protect short jobs
    if state.queue_len > q:
        return tier * task.weight / est * math.exp(-max(slack, 0.0) / (k * mean_est))
    return tier * task.weight / est * (1.0 + b * wait / est)

import math
def priority(task, state, k=0.5, m=2.0, q=4.0, b=0.5, c=2.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    slack = task.due - est - state.now
    mean_est = max(state.mean_est, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    guard = 1e6 if ratio >= c else 0.0
    if state.queue_len > q:
        atc = task.weight / est * math.exp(-max(slack, 0.0) / (k * mean_est))
        return guard + tier * atc * (1.0 + b * ratio)
    return guard + tier * task.weight / est * (1.0 + b * ratio)

