def priority(task, state, k=1.0, m=2.0, b=1.0, thresh=0.5, eps=1e-6):
    est = max(task.estimated_runtime, eps)
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    atc = tier * task.weight / est * math.exp(-slack / (k * max(state.mean_est, eps)))
    wait = state.now - task.release
    ratio = wait / est
    if ratio >= thresh:
        return atc * (1.0 + b * ratio)
    return atc

